import{_ as e,c as o,o as s,ae as n}from"./chunks/framework.CHDT0Kbg.js";const m=JSON.parse('{"title":"Solución de problemas","description":"","frontmatter":{},"headers":[],"relativePath":"es/guide/troubleshooting.md","filePath":"es/guide/troubleshooting.md","lastUpdated":1795170900000}'),r={name:"es/guide/troubleshooting.md"};function i(t,a,l,d,u,c){return s(),o("div",null,[...a[0]||(a[0]=[n('<h1 id="solucion-de-problemas" tabindex="-1">Solución de problemas <a class="header-anchor" href="#solucion-de-problemas" aria-label="Permalink to &quot;Solución de problemas&quot;">​</a></h1><p>Soluciones para los inconvenientes más comunes.</p><h2 id="una-pagina-no-carga" tabindex="-1">Una página no carga <a class="header-anchor" href="#una-pagina-no-carga" aria-label="Permalink to &quot;Una página no carga&quot;">​</a></h2><ul><li>Comprueba que otras páginas sí abran y vuelve a cargar con ⌘R.</li><li>Si tienes activa una lista de bloqueo de anuncios, pausálа un momento para ver si está bloqueando el sitio.</li><li>Prueba una ventana privada (⌘⇧N). Si allí funciona, borra las cookies del sitio desde los ajustes.</li></ul><h2 id="una-descarga-se-queda-atascada-o-incompleta" tabindex="-1">Una descarga se queda atascada o incompleta <a class="header-anchor" href="#una-descarga-se-queda-atascada-o-incompleta" aria-label="Permalink to &quot;Una descarga se queda atascada o incompleta&quot;">​</a></h2><ul><li>Abre el panel de descargas, pausa el elemento y reanúdalo.</li><li>Si falla un vídeo guardado desde una página, borra el archivo incompleto e inténtalo de nuevo. Los vídeos divididos se unen en un solo MP4; si falla la unión, las partes originales quedan en la carpeta de descargas.</li></ul><h2 id="no-se-importaron-los-marcadores" tabindex="-1">No se importaron los marcadores <a class="header-anchor" href="#no-se-importaron-los-marcadores" aria-label="Permalink to &quot;No se importaron los marcadores&quot;">​</a></h2><p>Primero exporta los marcadores de tu navegador anterior a un archivo HTML. Después, en Persim, abre el gestor de marcadores y elige <strong>Importar HTML</strong>. Las carpetas y los enlaces duplicados se ordenan automáticamente.</p><h2 id="no-se-detectan-videos" tabindex="-1">No se detectan vídeos <a class="header-anchor" href="#no-se-detectan-videos" aria-label="Permalink to &quot;No se detectan vídeos&quot;">​</a></h2><p>No todos los sitios ofrecen un archivo de vídeo guardable. Abre el panel de medios en la página; si no aparece nada, el sitio puede usar un tipo de reproducción que no se puede guardar directamente.</p><h2 id="la-app-va-lenta" tabindex="-1">La app va lenta <a class="header-anchor" href="#la-app-va-lenta" aria-label="Permalink to &quot;La app va lenta&quot;">​</a></h2><p>Cierra las pestañas que no uses o desactiva una suscripción de bloqueo que ya no necesites. Los permisos de los sitios se revisan en los ajustes.</p><h2 id="sigues-sin-solucion" tabindex="-1">Sigues sin solución <a class="header-anchor" href="#sigues-sin-solucion" aria-label="Permalink to &quot;Sigues sin solución&quot;">​</a></h2><p>Escribe a <strong><a href="mailto:persim@w3cub.com" target="_blank" rel="noreferrer">persim@w3cub.com</a></strong> y cuéntanos qué intentabas hacer; si puedes, adjunta una captura.</p>',14)])])}const h=e(r,[["render",i]]);export{m as __pageData,h as default};
